1	package checks
2	
3	import (
4		"context"
5		"strconv"
6		"strings"
7	
8		"lava-sensor-exercise/sensor/internal/probe"
9		"lava-sensor-exercise/sensor/internal/scan"
10	)
11	
12	// STORAGE_POSTURE is about data-at-rest and decommissioning hygiene on rented
13	// hardware. No check in this file ever opens a block device: what is on a disk
14	// is deliberately out of scope, and saying so is part of the answer.
15	
16	// ---------------------------------------------------------------------------
17	// DISK_ENCRYPTION_AT_REST
18	// ---------------------------------------------------------------------------
19	
20	type diskEncryptionAtRest struct{ meta }
21	
22	type dmDevice struct {
23		Name     string `json:"name"`
24		SysfsDir string `json:"sysfs_path"`
25		DMName   string `json:"dm_name,omitempty"`
26		DMUUID   string `json:"dm_uuid,omitempty"`
27		Crypt    bool   `json:"crypt"`
28		Errno    string `json:"errno,omitempty"`
29	}
30	
31	type blindSpot struct {
32		Mechanism  string `json:"mechanism"`
33		WhyUnknown string `json:"why_unknown"`
34		Evidence   string `json:"evidence_path_or_errno"`
35	}
36	
37	func (c diskEncryptionAtRest) Run(ctx context.Context, env *scan.Env) scan.Result {
38		var r scan.Result
39		finish := func(out scan.Result) scan.Result {
40			out.Observations, out.Fields = r.Observations, r.Fields
41			return out
42		}
43		// The verdict is scoped to dm-crypt/LUKS. "No dm mapping" is not "the disks
44		// are unencrypted" (L30) and the wording never says otherwise.
45		r.Field("scope", "dm-crypt/LUKS as visible to the kernel's device-mapper layer")
46	
47		blockNames, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
48		blockObs.LoadBearing = true
49		r.Add(blockObs)
50		mapperNames, mapperObs := env.Files.ReadDirNames("/dev/mapper", 512)
51		r.Add(mapperObs)
52		mounts := env.Mounts()
53		r.Add(mounts.Obs)
54	
55		var dms []dmDevice
56		cryptFound := false
57		uuidUnreadable := false
58		for _, n := range blockNames {
59			if !strings.HasPrefix(n, "dm-") {
60				continue
61			}
62			d := dmDevice{Name: n, SysfsDir: "/sys/block/" + n + "/dm"}
63			uuid, uObs := env.Files.ReadTrimmed("/sys/block/"+n+"/dm/uuid", probe.Tiny)
64			name, _ := env.Files.ReadTrimmed("/sys/block/"+n+"/dm/name", probe.Tiny)
65			d.DMUUID, d.DMName = uuid, name
66			if uObs.Status != probe.StatusOK {
67				d.Errno = uObs.Reason()
68				uuidUnreadable = true
69			}
70			// cryptsetup's own convention: the mapping's uuid is CRYPT-<type>-...
71			if strings.HasPrefix(uuid, "CRYPT-") {
72				d.Crypt, cryptFound = true, true
73			}
74			dms = append(dms, d)
75		}
76		r.Field("dm_devices", dms)
77		r.Field("dm_devices_found", int64(len(dms)))
78		r.Field("dev_mapper_entries", mapperNames)
79	
80		// The backing chain of every real mount.
81		type mountChain struct {
82			Mountpoint string   `json:"mountpoint"`
83			Source     string   `json:"source"`
84			FSType     string   `json:"fstype"`
85			Backing    []string `json:"backing_devices"`
86			Encrypted  bool     `json:"encrypted_by_dm_crypt"`
87		}
88		var chains []mountChain
89		rootEncrypted := false
90		for _, m := range mounts.Entries {
91			if !isRealFilesystem(m.FSType) {
92				continue
93			}
94			backing := backingDevices(env, m.MajorMinor)
95			mc := mountChain{Mountpoint: m.MountPoint, Source: m.Source, FSType: m.FSType, Backing: backing}
96			for _, b := range backing {
97				for _, d := range dms {
98					if d.Name == b && d.Crypt {
99						mc.Encrypted = true
100					}
101				}
102			}
103			if m.MountPoint == "/" {
104				rootEncrypted = mc.Encrypted
105			}
106			chains = append(chains, mc)
107		}
108		r.Field("mount_chain", chains)
109	
110		// Named blind spots, each with its own reason: an unknown that is not named
111		// is indistinguishable from a claim.
112		spots := []blindSpot{
113			{"self-encrypting drive / TCG Opal",
114				"every IOC_OPAL_* ioctl is gated on CAP_SYS_ADMIN and the kernel exposes no Opal state in sysfs; the drive model string cannot substitute, because vendors ship SED and non-SED SKUs under the same base part number",
115				"no sysfs attribute exists to read"},
116			{"filesystem-level encryption (ext4 fscrypt)",
117				"whether a filesystem uses fscrypt is recorded in its superblock, which needs root or dumpe2fs to read; kernel support for the feature is not use of it",
118				"/sys/fs/ext4/features/encryption (support only)"},
119			{"ZFS and btrfs native encryption",
120				"reported only where such a filesystem is mounted; the property lives in the pool or subvolume metadata",
121				"/proc/self/mountinfo fstype"},
122		}
123		if fe := env.Files.Stat("/sys/fs/ext4/features/encryption"); fe.Status == probe.StatusOK {
124			r.Field("ext4_fscrypt_kernel_support", true)
125		}
126		r.Field("blind_spots", spots)
127		if ct := env.Files.Stat("/etc/crypttab"); ct.Status == probe.StatusOK {
128			r.Add(ct)
129			r.Field("crypttab_present", true)
130		}
131	
132		switch {
133		case blockObs.Status != probe.StatusOK || mounts.Obs.Status != probe.StatusOK:
134			return finish(scan.Unknown(reasonOf(blockObs, mounts.Obs),
135				"the block device list or the mount table could not be read, so the backing chain of the mounted filesystems is unresolved and dm-crypt use can neither be confirmed nor ruled out"))
136		case uuidUnreadable:
137			return finish(scan.Unknown(scan.ReasonEACCES,
138				"a device-mapper mapping exists whose dm/uuid could not be read, so whether it is a dm-crypt mapping is unknown"))
139		case rootEncrypted:
140			return finish(scan.Pass(
141				"the root filesystem's backing chain reaches a device-mapper mapping whose dm/uuid carries the CRYPT- prefix, so dm-crypt/LUKS is in use for it"))
142		case cryptFound:
143			return finish(scan.Fail(scan.ReasonPolicy,
144				"dm-crypt/LUKS mappings exist on this machine but the root filesystem's backing chain does not pass through one, so the root filesystem is not protected by block-level encryption the kernel can see"))
145		default:
146			return finish(scan.Fail(scan.ReasonPolicy,
147				"the device-mapper and block device listings both completed and contain no CRYPT- mapping, so dm-crypt/LUKS is provably not in use for any mounted filesystem; this statement is scoped to dm-crypt/LUKS and does not assert that the media is unencrypted — the named blind spots in the evidence say what remains unknown"))
148		}
149	}
150	
151	func isRealFilesystem(fstype string) bool {
152		switch fstype {
153		case "proc", "sysfs", "devtmpfs", "devpts", "tmpfs", "cgroup", "cgroup2", "securityfs",
154			"pstore", "bpf", "configfs", "debugfs", "tracefs", "fusectl", "mqueue", "hugetlbfs",
155			"binfmt_misc", "autofs", "efivarfs", "ramfs", "rpc_pipefs", "nsfs", "overlay", "squashfs",
156			"9p", "drvfs", "none":
157			return false
158		}
159		return true
160	}
161	
162	// backingDevices walks from a mount's major:minor down to the physical devices
163	// underneath it, through slaves/ links.
164	func backingDevices(env *scan.Env, majmin string) []string {
165		name := blockNameFor(env, majmin)
166		if name == "" {
167			return []string{}
168		}
169		seen := map[string]bool{}
170		var out []string
171		var walk func(string, int)
172		walk = func(n string, depth int) {
173			if depth > 8 || seen[n] {
174				return
175			}
176			seen[n] = true
177			out = append(out, n)
178			slaves, obs := env.Files.ReadDirNames("/sys/block/"+n+"/slaves", 64)
179			if obs.Status != probe.StatusOK {
180				// A partition's parent is its containing directory, not a slave.
181				if parent := wholeDiskOf(env, n); parent != "" && parent != n {
182					walk(parent, depth+1)
183				}
184				return
185			}
186			for _, s := range slaves {
187				walk(s, depth+1)
188			}
189		}
190		walk(name, 0)
191		return out
192	}
193	
194	// blockNameFor resolves a major:minor to a kernel block device name, including
195	// partitions, without opening anything.
196	func blockNameFor(env *scan.Env, majmin string) string {
197		names, obs := env.Files.ReadDirNames("/sys/block", 1024)
198		if obs.Status != probe.StatusOK {
199			return ""
200		}
201		for _, n := range names {
202			if v, o := env.Files.ReadTrimmed("/sys/block/"+n+"/dev", probe.Tiny); o.Status == probe.StatusOK && v == majmin {
203				return n
204			}
205			parts, po := env.Files.ReadDirNames("/sys/block/"+n, 1024)
206			if po.Status != probe.StatusOK {
207				continue
208			}
209			for _, p := range parts {
210				if !strings.HasPrefix(p, n) || p == n {
211					continue
212				}
213				if v, o := env.Files.ReadTrimmed("/sys/block/"+n+"/"+p+"/dev", probe.Tiny); o.Status == probe.StatusOK && v == majmin {
214					return p
215				}
216			}
217		}
218		return ""
219	}
220	
221	func wholeDiskOf(env *scan.Env, part string) string {
222		names, obs := env.Files.ReadDirNames("/sys/block", 1024)
223		if obs.Status != probe.StatusOK {
224			return ""
225		}
226		for _, n := range names {
227			if n != part && strings.HasPrefix(part, n) {
228				return n
229			}
230		}
231		return ""
232	}
233	
234	// ---------------------------------------------------------------------------
235	// ROOT_FILESYSTEM_REDUNDANCY
236	// ---------------------------------------------------------------------------
237	
238	type rootFilesystemRedundancy struct{ meta }
239	
240	type mdArray struct {
241		Name      string `json:"name"`
242		Level     string `json:"level,omitempty"`
243		Degraded  string `json:"degraded,omitempty"`
244		RaidDisks string `json:"raid_disks,omitempty"`
245		Errno     string `json:"errno,omitempty"`
246	}
247	
248	var redundantLevels = map[string]bool{"raid1": true, "raid5": true, "raid6": true, "raid10": true}
249	
250	func (c rootFilesystemRedundancy) Run(ctx context.Context, env *scan.Env) scan.Result {
251		var r scan.Result
252		finish := func(out scan.Result) scan.Result {
253			out.Observations, out.Fields = r.Observations, r.Fields
254			return out
255		}
256	
257		mounts := env.Mounts()
258		mounts.Obs.LoadBearing = true
259		r.Add(mounts.Obs)
260		var rootMM, rootFS, rootSrc string
261		for _, m := range mounts.Entries {
262			if m.MountPoint == "/" {
263				rootMM, rootFS, rootSrc = m.MajorMinor, m.FSType, m.Source
264			}
265		}
266		if rootMM == "" {
267			return finish(scan.Unknown(scan.ReasonParse,
268				"the root filesystem could not be located in the mount table, so its backing chain is unresolved"))
269		}
270		backing := backingDevices(env, rootMM)
271		r.Field("root_mount", map[string]string{"source": rootSrc, "fstype": rootFS, "major_minor": rootMM})
272		r.Field("backing_devices", backing)
273	
274		// md arrays. /proc/mdstat always lists the compiled-in personalities, so a
275		// populated Personalities: line is not an array (T-S2).
276		mdstat := env.Files.Read("/proc/mdstat", probe.Small)
277		r.Add(mdstat)
278		blockNames, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
279		r.Add(blockObs)
280		var arrays []mdArray
281		for _, n := range blockNames {
282			if !strings.HasPrefix(n, "md") {
283				continue
284			}
285			a := mdArray{Name: n}
286			a.Level, _ = env.Files.ReadTrimmed("/sys/block/"+n+"/md/level", probe.Tiny)
287			a.Degraded, _ = env.Files.ReadTrimmed("/sys/block/"+n+"/md/degraded", probe.Tiny)
288			a.RaidDisks, _ = env.Files.ReadTrimmed("/sys/block/"+n+"/md/raid_disks", probe.Tiny)
289			arrays = append(arrays, a)
290		}
291		r.Field("md_arrays", arrays)
292		if mdstat.Status == probe.StatusOK {
293			r.Field("mdstat_excerpt", excerptLines(mdstat.Value, 12))
294			r.Field("mdstat_note", "/proc/mdstat always lists the compiled-in personalities; a populated Personalities: line is not an array")
295		}
296	
297		// A hardware RAID controller presents one logical device and its health
298		// needs a vendor CLI. Gate on the PCI class, never on a controller name.
299		var raidControllers []string
300		if devs, obs := env.Files.ReadDirNames("/sys/bus/pci/devices", 1024); obs.Status == probe.StatusOK {
301			for _, d := range devs {
302				cls, o := env.Files.ReadTrimmed("/sys/bus/pci/devices/"+d+"/class", probe.Tiny)
303				if o.Status != probe.StatusOK {
304					continue
305				}
306				if strings.HasPrefix(strings.ToLower(cls), "0x0104") {
307					drv, _ := env.Files.ReadLinkBase("/sys/bus/pci/devices/" + d + "/driver")
308					raidControllers = append(raidControllers, d+" (class "+cls+", driver "+firstNonEmpty(drv, "none")+")")
309				}
310			}
311		}
312		r.Field("pci_raid_controllers", raidControllers)
313	
314		// Redundancy layer, decided from the backing chain.
315		layer := "none"
316		degraded := false
317		for _, b := range backing {
318			switch {
319			case strings.HasPrefix(b, "md"):
320				for _, a := range arrays {
321					if a.Name == b && redundantLevels[a.Level] {
322						layer = "md/" + a.Level
323						degraded = a.Degraded != "" && a.Degraded != "0"
324					}
325				}
326			case strings.HasPrefix(b, "dm-"):
327				if uuid, o := env.Files.ReadTrimmed("/sys/block/"+b+"/dm/uuid", probe.Tiny); o.Status == probe.StatusOK && strings.HasPrefix(uuid, "DM-RAID-") {
328					layer = "dm-raid"
329				}
330			}
331		}
332		if rootFS == "btrfs" {
333			if devs, obs := env.Files.ReadDirNames("/sys/fs/btrfs", 64); obs.Status == probe.StatusOK && len(devs) > 0 {
334				r.Field("btrfs_filesystems", devs)
335			}
336			if layer == "none" {
337				return finish(scan.Unknown(scan.ReasonUtilMiss,
338					"the root filesystem is btrfs, whose redundancy profile lives in filesystem metadata that this sensor does not read, so whether it survives a device loss is unknown"))
339			}
340		}
341		if rootFS == "zfs" && layer == "none" {
342			return finish(scan.Unknown(scan.ReasonUtilMiss,
343				"the root filesystem is ZFS, whose vdev layout is not exposed in sysfs, so whether it survives a device loss is unknown"))
344		}
345		r.Field("redundancy_layer", layer)
346	
347		// Idle devices that could provide redundancy make the finding actionable.
348		var spares []string
349		for _, n := range blockNames {
350			if hasAnyPrefix(n, excludedBlockPrefixes) || strings.HasPrefix(n, "dm-") || strings.HasPrefix(n, "md") {
351				continue
352			}
353			if !deviceInUse(env, n, mounts) {
354				spares = append(spares, n)
355			}
356		}
357		r.Field("idle_devices_present", spares)
358	
359		physical := 0
360		for _, b := range backing {
361			if !strings.HasPrefix(b, "dm-") && !strings.HasPrefix(b, "md") {
362				physical++
363			}
364		}
365	
366		switch {
367		case len(raidControllers) > 0 && layer == "none":
368			return finish(scan.Unknown(scan.ReasonUtilMiss,
369				"a PCI RAID controller (class 0104) is present, so the root filesystem's single logical device may be backed by hardware redundancy this operating system cannot see; a vendor CLI would be needed to establish it"))
370		case degraded:
371			return finish(scan.Fail(scan.ReasonPolicy,
372				"the root filesystem sits on a "+layer+" array that is currently degraded, so it may not survive another device loss"))
373		case layer != "none":
374			return finish(scan.Pass("the root filesystem's backing chain passes through a " + layer +
375				" layer reporting zero degraded members, so it survives the loss of a single device"))
376		case blockObs.Status != probe.StatusOK || mdstat.Status != probe.StatusOK:
377			return finish(scan.Unknown(reasonOf(blockObs, mdstat),
378				"the redundancy enumerations did not all complete, so a single-device root cannot be asserted"))
379		case physical <= 1:
380			msg := "the root filesystem resolves to a single physical device (" + strings.Join(backing, " -> ") +
381				") and every redundancy enumeration completed without finding an md array, a dm-raid target or a multi-device pool, so the loss of that device loses the root filesystem"
382			if len(spares) > 0 {
383				msg += "; " + itoa(int64(len(spares))) + " attached device(s) (" + strings.Join(spares, ", ") +
384					") are idle and could provide redundancy. A single-device root may be a deliberate rebuild-on-failure choice"
385			}
386			return finish(scan.Fail(scan.ReasonPolicy, msg))
387		default:
388			return finish(scan.Unknown(scan.ReasonParse,
389				"the root filesystem's backing chain resolved to "+itoa(int64(physical))+
390					" devices without an identifiable redundancy layer, so whether it survives a device loss is unresolved"))
391		}
392	}
393	
394	func excerptLines(s string, n int) string {
395		lines := strings.Split(strings.TrimSpace(s), "\n")
396		if len(lines) > n {
397			lines = lines[:n]
398		}
399		return strings.Join(lines, "\n")
400	}
401	
402	// ---------------------------------------------------------------------------
403	// UNUSED_ATTACHED_BLOCK_DEVICES
404	// ---------------------------------------------------------------------------
405	
406	type unusedAttachedBlockDevices struct{ meta }
407	
408	type blockDeviceUse struct {
409		Name               string   `json:"name"`
410		SizeBytes          int64    `json:"size_bytes"`
411		Partitions         []string `json:"partitions"`
412		Holders            []string `json:"holders"`
413		Slaves             []string `json:"slaves"`
414		Mountpoints        []string `json:"mountpoints"`
415		UdevFSType         string   `json:"udev_fstype"`
416		UdevRecordPath     string   `json:"udev_record_path"`
417		UdevRecordReadable bool     `json:"udev_record_readable"`
418		InSwap             bool     `json:"in_swap"`
419		InUse              bool     `json:"in_use"`
420		InUseBasis         []string `json:"in_use_basis"`
421	}
422	
423	const remanenceStatement = "unknown by design — the sensor does not open the device to find out what is on it"
424	
425	func (c unusedAttachedBlockDevices) Run(ctx context.Context, env *scan.Env) scan.Result {
426		var r scan.Result
427		finish := func(out scan.Result) scan.Result {
428			out.Observations, out.Fields = r.Observations, r.Fields
429			return out
430		}
431		r.Field("device_not_opened", true)
432		r.Field("remanence", remanenceStatement)
433		r.Field("udev_caveat", "fstype comes from the udev database as recorded at the last uevent, not from a read of the disk; a filesystem created afterwards would be invisible")
434	
435		names, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
436		blockObs.LoadBearing = true
437		r.Add(blockObs)
438		if blockObs.Status != probe.StatusOK {
439			return finish(scan.Unknown(blockObs.Reason(),
440				"/sys/block could not be listed ("+blockObs.Reason()+"), so which block devices are attached is unknown"))
441		}
442		mounts := env.Mounts()
443		r.Add(mounts.Obs)
444		swaps := env.Files.Read("/proc/swaps", probe.Small)
445		r.Add(swaps)
446	
447		var devices []blockDeviceUse
448		var idle []string
449		udevUnreadable := false
450	
451		for _, n := range names {
452			if hasAnyPrefix(n, excludedBlockPrefixes) {
453				continue
454			}
455			d := blockDeviceUse{Name: n, Partitions: []string{}, Holders: []string{}, Slaves: []string{},
456				Mountpoints: []string{}, InUseBasis: []string{}}
457			if v, o := env.Files.ReadTrimmed("/sys/block/"+n+"/size", probe.Tiny); o.Status == probe.StatusOK {
458				if sectors, err := strconv.ParseInt(v, 10, 64); err == nil {
459					d.SizeBytes = sectors * sectorBytes
460				}
461			}
462			if ents, o := env.Files.ReadDirNames("/sys/block/"+n, 1024); o.Status == probe.StatusOK {
463				for _, e := range ents {
464					if e != n && strings.HasPrefix(e, n) && env.Files.Exists("/sys/block/"+n+"/"+e+"/partition") {
465						d.Partitions = append(d.Partitions, e)
466					}
467				}
468			}
469			if hs, o := env.Files.ReadDirNames("/sys/block/"+n+"/holders", 64); o.Status == probe.StatusOK {
470				d.Holders = hs
471			}
472			if sl, o := env.Files.ReadDirNames("/sys/block/"+n+"/slaves", 64); o.Status == probe.StatusOK {
473				d.Slaves = sl
474			}
475			majmin, _ := env.Files.ReadTrimmed("/sys/block/"+n+"/dev", probe.Tiny)
476			d.UdevRecordPath = "/run/udev/data/b" + majmin
477			udevObs := env.Files.Read(d.UdevRecordPath, probe.Small)
478			if udevObs.Status == probe.StatusOK {
479				d.UdevRecordReadable = true
480				for _, ln := range strings.Split(udevObs.Value, "\n") {
481					if k, v, ok := strings.Cut(strings.TrimPrefix(ln, "E:"), "="); ok && k == "ID_FS_TYPE" {
482						d.UdevFSType = v
483					}
484				}
485			} else if udevObs.Status != probe.StatusENOENT {
486				udevUnreadable = true
487			}
488			for _, m := range mounts.Entries {
489				if m.MajorMinor == majmin || strings.Contains(m.Source, "/"+n) {
490					d.Mountpoints = append(d.Mountpoints, m.MountPoint)
491				}
492			}
493			if swaps.Status == probe.StatusOK && strings.Contains(swaps.Value, "/"+n) {
494				d.InSwap = true
495			}
496	
497			if len(d.Partitions) > 0 {
498				d.InUseBasis = append(d.InUseBasis, "has "+itoa(int64(len(d.Partitions)))+" partition(s)")
499			}
500			if len(d.Holders) > 0 {
501				d.InUseBasis = append(d.InUseBasis, "has holders")
502			}
503			if len(d.Mountpoints) > 0 {
504				d.InUseBasis = append(d.InUseBasis, "is mounted")
505			}
506			if d.InSwap {
507				d.InUseBasis = append(d.InUseBasis, "is a swap device")
508			}
509			if d.UdevFSType != "" {
510				d.InUseBasis = append(d.InUseBasis, "udev recorded filesystem type "+d.UdevFSType)
511			}
512			d.InUse = len(d.InUseBasis) > 0
513			if !d.InUse {
514				idle = append(idle, n)
515			}
516			devices = append(devices, d)
517		}
518		r.Field("devices", devices)
519	
520		switch {
521		case mounts.Obs.Status != probe.StatusOK || swaps.Status != probe.StatusOK:
522			return finish(scan.Unknown(reasonOf(mounts.Obs, swaps),
523				"the mount table or the swap list could not be read, so whether every attached device is accounted for is unknown"))
524		case udevUnreadable && len(idle) > 0:
525			return finish(scan.Unknown(scan.ReasonEACCES,
526				"a device has no partition, holder, mount or swap entry, but its udev record could not be read, so whether it carries a filesystem signature is an open question"))
527		case len(idle) > 0:
528			return finish(scan.Fail(scan.ReasonPolicy,
529				"attached but unaccounted for: "+strings.Join(idle, ", ")+
530					" — no partition table and no filesystem signature known to udev, no holder, no mount and no swap entry. "+
531					"Whether prior-tenant data remains on it is "+remanenceStatement))
532		default:
533			return finish(scan.Pass(
534				"every attached physical block device is accounted for by a partition, a mount, a holder relationship, a swap entry or a udev filesystem signature (" +
535					itoa(int64(len(devices))) + " device(s))"))
536		}
537	}
538	
539	func deviceInUse(env *scan.Env, n string, mounts *scan.MountTable) bool {
540		if ents, o := env.Files.ReadDirNames("/sys/block/"+n, 1024); o.Status == probe.StatusOK {
541			for _, e := range ents {
542				if e != n && strings.HasPrefix(e, n) && env.Files.Exists("/sys/block/"+n+"/"+e+"/partition") {
543					return true
544				}
545			}
546		}
547		if hs, o := env.Files.ReadDirNames("/sys/block/"+n+"/holders", 64); o.Status == probe.StatusOK && len(hs) > 0 {
548			return true
549		}
550		majmin, _ := env.Files.ReadTrimmed("/sys/block/"+n+"/dev", probe.Tiny)
551		for _, m := range mounts.Entries {
552			if m.MajorMinor == majmin {
553				return true
554			}
555		}
556		return false
557	}
558	
559	// ---------------------------------------------------------------------------
560	// MEDIA_HEALTH_VISIBILITY
561	// ---------------------------------------------------------------------------
562	
563	type mediaHealthVisibility struct{ meta }
564	
565	type healthSignal struct {
566		Path  string `json:"path"`
567		Value string `json:"value,omitempty"`
568		Errno string `json:"errno,omitempty"`
569		Clean *bool  `json:"clean,omitempty"`
570	}
571	
572	func (c mediaHealthVisibility) Run(ctx context.Context, env *scan.Env) scan.Result {
573		var r scan.Result
574		finish := func(out scan.Result) scan.Result {
575			out.Observations, out.Fields = r.Observations, r.Fields
576			return out
577		}
578		r.Field("capability_required", "CAP_SYS_ADMIN on the NVMe or SCSI character device for SMART; the NVMe admin passthrough is gated by a capability check, not by group membership")
579		r.Field("remediation_note", "obtaining SMART here requires CAP_SYS_ADMIN — adding the account to the disk group would not grant it, and recommending that would be a wrong instruction")
580	
581		var signals []healthSignal
582		var adverse []string
583		readableCount := 0
584	
585		// ext4 error counters.
586		if devs, obs := env.Files.ReadDirNames("/sys/fs/ext4", 64); obs.Status == probe.StatusOK {
587			r.Add(obs)
588			for _, d := range devs {
589				if d == "features" {
590					continue
591				}
592				for _, attr := range []string{"errors_count", "first_error_time", "lifetime_write_kbytes"} {
593					p := "/sys/fs/ext4/" + d + "/" + attr
594					v, o := env.Files.ReadTrimmed(p, probe.Tiny)
595					s := healthSignal{Path: p, Value: v, Errno: o.Reason()}
596					if o.Status == probe.StatusOK && attr == "errors_count" {
597						readableCount++
598						clean := v == "0"
599						s.Clean = &clean
600						if !clean {
601							adverse = append(adverse, "ext4 on "+d+" has recorded "+v+" filesystem error(s)")
602						}
603					}
604					signals = append(signals, s)
605				}
606			}
607		}
608	
609		// Device state and md degradation.
610		names, blockObs := env.Files.ReadDirNames("/sys/block", 1024)
611		r.Add(blockObs)
612		for _, n := range names {
613			if hasAnyPrefix(n, excludedBlockPrefixes) {
614				continue
615			}
616			if strings.HasPrefix(n, "md") {
617				p := "/sys/block/" + n + "/md/degraded"
618				v, o := env.Files.ReadTrimmed(p, probe.Tiny)
619				s := healthSignal{Path: p, Value: v, Errno: o.Reason()}
620				if o.Status == probe.StatusOK {
621					readableCount++
622					clean := v == "0"
623					s.Clean = &clean
624					if !clean {
625						adverse = append(adverse, "md array "+n+" reports "+v+" degraded member(s)")
626					}
627				}
628				signals = append(signals, s)
629				continue
630			}
631			p := "/sys/block/" + n + "/device/state"
632			v, o := env.Files.ReadTrimmed(p, probe.Tiny)
633			if o.Status != probe.StatusOK {
634				continue
635			}
636			readableCount++
637			clean := v == "live" || v == "running"
638			signals = append(signals, healthSignal{Path: p, Value: v, Clean: &clean})
639			if !clean {
640				adverse = append(adverse, "device "+n+" reports state "+v)
641			}
642		}
643		r.Field("readable_signals", signals)
644	
645		// SMART, behind sysfs. Both tools are fallbacks and both are expected to be
646		// denied or absent; the errno is the evidence.
647		smartObtained := false
648		var smartAttempts []string
649		for _, n := range names {
650			if !strings.HasPrefix(n, "nvme") && !strings.HasPrefix(n, "sd") {
651				continue
652			}
653			obs := env.Runner.Run(ctx, probe.Spec{Name: "smartctl", Args: []string{"-H", "-j", "/dev/" + n},
654				Budget: 3000000000, Purpose: "drive health (JSON only; a tool that rejects -j yields unknown, never positional parsing)"})
655			r.Add(obs)
656			smartAttempts = append(smartAttempts, "smartctl -H -j /dev/"+n+" -> "+string(obs.Status)+" "+obs.Reason())
657			if obs.Status == probe.StatusOK && strings.Contains(obs.Value, "{") {
658				smartObtained = true
659				if strings.Contains(obs.Value, `"passed":false`) {
660					adverse = append(adverse, "SMART health self-assessment failed for /dev/"+n)
661				}
662				break
663			}
664			if strings.HasPrefix(n, "nvme") {
665				nobs := env.Runner.Run(ctx, probe.Spec{Name: "nvme", Args: []string{"smart-log", "/dev/" + n},
666					Budget: 3000000000, Purpose: "NVMe health (expected to be denied without CAP_SYS_ADMIN; the errno is the evidence)"})
667				r.Add(nobs)
668				smartAttempts = append(smartAttempts, "nvme smart-log /dev/"+n+" -> "+string(nobs.Status)+" "+nobs.Reason())
669				if nobs.Status == probe.StatusOK {
670					smartObtained = true
671					break
672				}
673			}
674			break
675		}
676		r.Field("smart_attempts", smartAttempts)
677		r.Field("smart_obtained", smartObtained)
678	
679		switch {
680		case len(adverse) > 0:
681			return finish(scan.Fail(scan.ReasonPolicy,
682				"a readable health signal reports a problem: "+strings.Join(adverse, "; ")))
683		case smartObtained:
684			return finish(scan.Pass("drive health telemetry is readable by this account and reports no failure"))
685		case readableCount > 0:
686			return finish(scan.Unknown(scan.ReasonEACCES,
687				"SMART telemetry is not obtainable by this account ("+strings.Join(smartAttempts, "; ")+
688					"), so media health itself is unknown; the "+itoa(int64(readableCount))+
689					" readable adjacent signals are in evidence and are all clean, but a filesystem error counter is not media health"))
690		default:
691			return finish(scan.Unknown(scan.ReasonEACCES,
692				"no health signal was readable at all: SMART needs a capability this account does not have, and no filesystem or device-state counter could be read"))
693		}
694	}
