88				return finish(scan.Unknown(unresolvedReason(oracle, cfg),
89					"the effective permitrootlogin could not be established: "+unresolvedDetail(oracle, cfg)))
90			}
91			effective = normalisePermitRootLogin(d.value)
92			source = "compiled-in default"
