96		}
97	
98		r.Field("config_resolution", res)
99		r.Field("effective_value", effective)
100		r.Field("effective_value_source", source)
101		r.Field("conditional_blocks", cfg.MatchBlocks)
102	
103		// 4. A Match block scoping this keyword makes a global verdict
104		//    evidence-only: the host-wide answer is contested by the conditional
105		//    one (L17, F29).
