247	// rootAuthorizedKeyPaths expands the daemon's effective authorizedkeysfile for
248	// root. OpenSSH resolves a relative path against the user's home directory and
249	// substitutes %h (home), %u (user name) and %% (a literal percent).
250	func rootAuthorizedKeyPaths(oracle *scan.SSHDOracle, rootHome string) (paths []string, source string) {
251		if v, ok := oracle.Value("authorizedkeysfile"); ok && strings.TrimSpace(v) != "" {
252			source = "sshd -G authorizedkeysfile"
253			for _, tok := range splitArgs(v) {
254				if isNoneValue(tok) {
255					continue
256				}
257				paths = append(paths, expandAuthorizedKeysToken(tok, rootHome))
258			}
259		}
260		if len(paths) == 0 {
261			source = "default AuthorizedKeysFile path (the daemon did not report one)"
262			paths = []string{rootHome + "/.ssh/authorized_keys"}
263		}
264		return paths, source
265	}
266	
267	func expandAuthorizedKeysToken(tok, home string) string {
268		var b strings.Builder
269		for i := 0; i < len(tok); i++ {
270			if tok[i] == '%' && i+1 < len(tok) {
271				switch tok[i+1] {
272				case 'h':
273					b.WriteString(home)
274					i++
275					continue
276				case 'u':
277					b.WriteString("root")
278					i++
279					continue
280				case '%':
281					b.WriteByte('%')
282					i++
283					continue
284				}
285			}
286			b.WriteByte(tok[i])
287		}
288		out := b.String()
289		if !strings.HasPrefix(out, "/") {
290			out = home + "/" + out
291		}
292		return out
293	}
294	
295	// homeOf resolves an account's home directory from /etc/passwd. No exec, and a
296	// documented convention rather than a guess when the file cannot be read.
297	func homeOf(f probe.Files, user string) string {
298		obs := f.Read("/etc/passwd", probe.Large)
299		if obs.Status == probe.StatusOK {
300			for _, ln := range strings.Split(obs.Value, "\n") {
301				fields := strings.Split(strings.TrimSpace(ln), ":")
302				if len(fields) >= 6 && fields[0] == user && fields[5] != "" {
303					return strings.TrimRight(fields[5], "/")
304				}
305			}
306		}
307		if user == "root" {
308			return rootHomeDefault
309		}
310		return "/home/" + user
311	}
312	
313	const rootHomeDefault = "/root"
314	
315	func parentDir(p string) string {
316		if i := strings.LastIndexByte(p, '/'); i > 0 {
317			return p[:i]
318		}
319		return "/"
320	}
321	
322	func isNoneValue(v string) bool {
323		t := strings.ToLower(strings.TrimSpace(v))
324		return t == "" || t == "none"
325	}
326	
327	func renderDirective(v string, known bool) string {
328		if !known {
329			return "unknown (not reported by the daemon)"
330		}
331		if strings.TrimSpace(v) == "" {
332			return "none"
333		}
334		return v
335	}
336	
337	// conflictingMatch returns a Match-scoped occurrence whose verdict class
338	// differs from the global one. A Match that is strictly more restrictive does
339	// not invalidate a global fail.
340	func conflictingMatch(res sshdResolution, global string) (sshdOccurrence, bool) {
341		for _, occ := range res.ConditionalBlocks {
342			if verdictClass(normalisePermitRootLogin(occ.Value)) != verdictClass(global) {
343				return occ, true
344			}
345		}
346		return sshdOccurrence{}, false
347	}
348	
349	func verdictClass(v string) string {
350		switch v {
351		case "no":
352			return "refused"
353		case "yes":
354			return "permitted"
355		case "prohibit-password", "forced-commands-only":
356			return "key-only"
357		}
358		return "unknown"
359	}
360	
361	// sshdIsPresent reports whether there is evidence of an SSH daemon at all: a
362	// binary that could be executed, or a configuration chain that was read.
363	func sshdIsPresent(oracle *scan.SSHDOracle, cfg *sshdConfig) bool {
364		if oracle.Obs.Status != probe.StatusUtilityMissing {
365			return true
366		}
367		return cfg.Resolved
368	}
369	
370	// unresolvedReason picks the reason that is actually actionable.
371	//
372	// A daemon that exists but did not answer inside its budget (TIMEOUT) or failed
373	// for its own reasons (EXECUTION_ERROR) is a stronger signal than "the config
374	// file is not there", so it wins; a missing binary is weaker than a denied or
375	// absent config chain, so the chain wins over it.
376	func unresolvedReason(oracle *scan.SSHDOracle, cfg *sshdConfig) string {
377		switch oracle.Obs.Status {
378		case probe.StatusTimeout, probe.StatusExecError:
379			if r := oracle.Obs.Reason(); r != "" {
380				return r
381			}
382		}
383		if cfg.RootObs.Status != probe.StatusOK && cfg.RootObs.Status != "" {
384			if r := cfg.RootObs.Reason(); r != "" {
385				return r
386			}
387		}
388		if r := oracle.Obs.Reason(); r != "" {
389			return r
390		}
391		return scan.ReasonENOENT
392	}
393	
394	func unresolvedDetail(oracle *scan.SSHDOracle, cfg *sshdConfig) string {
395		parts := []string{"sshd -G: " + string(oracle.Obs.Status)}
396		if oracle.ParseError != "" {
397			parts = append(parts, "oracle parse: "+oracle.ParseError)
398		}
399		if cfg.RootObs.Status == probe.StatusOK {
400			parts = append(parts, "the config chain was read ("+strings.Join(cfg.Files, ", ")+
401				") but does not set the directive, and no compiled-in default is citable for this distribution")
402		} else {
403			parts = append(parts, cfg.RootPath+": "+string(cfg.RootObs.Status))
404		}
405		return strings.Join(parts, "; ")
406	}
407	
408	func reasonOf(obs ...probe.Observation) string {
409		for _, o := range obs {
410			if o.Status != probe.StatusOK && o.Status != "" {
411				if r := o.Reason(); r != "" {
412					return r
413				}
414			}
415		}
416		return scan.ReasonEACCES
417	}
418	
419	// fileMeta is the file_metadata evidence shape for a single path.
420	type fileMeta struct {
421		Path     string `json:"path"`
422		Exists   *bool  `json:"exists,omitempty"`
423		FileType string `json:"file_type,omitempty"`
424		Mode     *int64 `json:"mode,omitempty"`
425		UID      *int64 `json:"uid,omitempty"`
426		GID      *int64 `json:"gid,omitempty"`
427		Size     *int64 `json:"size,omitempty"`
428		Errno    string `json:"errno,omitempty"`
429		Status   string `json:"status"`
430	}
431	
432	func renderMeta(obs probe.Observation) fileMeta {
433		fm := fileMeta{Path: obs.Source, Status: string(obs.Status), Errno: obs.Reason()}
434		if obs.Meta != nil {
435			fm.Exists = obs.Meta.Exists
436			fm.FileType = obs.Meta.FileType
437			fm.Mode = obs.Meta.Mode
438			fm.UID = obs.Meta.UID
439			fm.GID = obs.Meta.GID
440			fm.Size = obs.Meta.Size
441		}
442		return fm
443	}
444	
445	func itoa(n int64) string {
446		if n == 0 {
447			return "0"
448		}
449		neg := n < 0
450		if neg {
451			n = -n
452		}
453		var b [20]byte
454		i := len(b)
455		for n > 0 {
456			i--
457			b[i] = byte('0' + n%10)
458			n /= 10
459		}
460		if neg {
461			i--
462			b[i] = '-'
463		}
464		return string(b[i:])
465	}
466	
467	func quote(s string) string { return `"` + s + `"` }
