		m := a.(map[string]any)
		if m["path"] == "/etc/cloud/cloud.cfg.d/99-keys.cfg" {
			if m["class"] != "payload" {
				t.Errorf("a drop-in declaring ssh_authorized_keys is payload: %v", m)
