			if err == nil && comm != "" {
				res.Owners[inode] = comm + " (pid " + n + ")"
			}
		}
	}
	res.ElapsedMS = env.Now().Sub(start).Milliseconds()
	if !res.Complete {
		obs.Truncated = true
		obs.Detail = "socket-owner attribution stopped early: " + res.StoppedBy +
			"; listeners it did not reach are unattributed, not unowned"
	}
	return res, obs
}

