1	package scan
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"sort"
8		"strings"
9	
10		"lava-sensor-exercise/sensor/internal/probe"
11	)
12	
13	// Evidence must entail the verdict.
14	//
15	// The failure this file exists to stop is not a typo in one check: it is a
16	// whole class. A check gathers observations, some of which failed, and then
17	// writes a sentence asserting that everything was seen — "enumerated
18	// successfully", "proven by a successful listing", "every enumeration
19	// completed". The structured evidence sitting next to that sentence contradicts
20	// it. A reader who trusts the sentence is wrong; a reader who trusts the
21	// evidence must distrust the sensor. That is worse than reporting nothing.
22	//
23	// So the link between the two is made mechanical here rather than left to each
24	// check's prose: the completeness statement is GENERATED from the observations,
25	// a claim of completeness that the observations do not support downgrades the
26	// finding, and TestEvidenceEntailsVerdict fails the build on any violation.
27	
28	// Completeness is the generated account of what was and was not observed. It is
29	// attached to every finding's evidence.
30	type Completeness struct {
31		ObservationsTotal int64    `json:"observations_total"`
32		ObservationsOK    int64    `json:"observations_ok"`
33		LoadBearingTotal  int64    `json:"load_bearing_total"`
34		LoadBearingOK     int64    `json:"load_bearing_ok"`
35		NotOK             []string `json:"not_ok"`
36		// AbsenceProvable is true only when every load-bearing observation
37		// succeeded in full. It is the precondition for any sentence that says
38		// something was not found.
39		AbsenceProvable bool   `json:"absence_provable"`
40		Statement       string `json:"statement"`
41	}
42	
43	// completenessClaims are phrases that assert an enumeration finished or that
44	// something is provably absent. A check may use one only when the observations
45	// entail it; the test at the bottom of this file enforces that over the whole
46	// roster.
47	var completenessClaims = []string{
48		"enumerated successfully",
49		"were all enumerated",
50		"were both enumerated",
51		"every enumeration completed",
52		"the enumeration completed",
53		"every redundancy enumeration completed",
54		"completed without finding",
55		"proven by a successful listing",
56		"proven by successful listing",
57		"proven by successful stats",
58		"proven by a successful stat",
59		"was listed successfully",
60		"listed successfully",
61		"proven absent",
62		"a proven negative",
63		"provably not in use",
64		"every candidate was resolved",
65		"resolved to not-found across",
66		"listings both completed",
67		"all three listings",
68	}
69	
70	// claimsCompleteness reports the first completeness claim a detail makes.
71	func claimsCompleteness(detail string) (string, bool) {
72		d := strings.ToLower(detail)
73		for _, c := range completenessClaims {
74			if strings.Contains(d, c) {
75				return c, true
76			}
77		}
78		return "", false
79	}
80	
81	// clean reports whether an observation answered its question in full.
82	//
83	// A truncated read is a prefix, not a value, so it is not clean even at status
84	// OK. An ENOENT the check marked AbsenceProven is clean: the path resolved and
85	// nothing was there, which is exactly the observation an absence claim needs.
86	func clean(o probe.Observation) bool {
87		if o.Truncated {
88			return false
89		}
90		return o.Status == probe.StatusOK ||
91			(o.Status == probe.StatusENOENT && o.AbsenceProven)
92	}
93	
94	// completenessOf builds the generated account. Absence is provable only from
95	// load-bearing observations that all succeeded: a check with no load-bearing
96	// observation has not shown that it looked anywhere, so it may not say that it
97	// looked everywhere.
98	func completenessOf(obs []probe.Observation) Completeness {
99		c := Completeness{NotOK: []string{}}
100		for _, o := range obs {
101			c.ObservationsTotal++
102			if clean(o) {
103				c.ObservationsOK++
104			}
105			if o.LoadBearing {
106				c.LoadBearingTotal++
107				if clean(o) {
108					c.LoadBearingOK++
109				} else {
110					c.NotOK = append(c.NotOK, o.Source+" ("+notOKLabel(o)+")")
111				}
112			}
113		}
114		sort.Strings(c.NotOK)
115		c.AbsenceProvable = c.LoadBearingTotal > 0 && c.LoadBearingOK == c.LoadBearingTotal
116		c.Statement = completenessStatement(c)
117		return c
118	}
119	
120	func notOKLabel(o probe.Observation) string {
121		if o.Status == probe.StatusOK && o.Truncated {
122			return "OK but truncated"
123		}
124		if r := o.Reason(); r != "" {
125			return r
126		}
127		return string(o.Status)
128	}
129	
130	// completenessStatement is the sentence a check is no longer allowed to write
131	// for itself.
132	func completenessStatement(c Completeness) string {
133		switch {
134		case c.LoadBearingTotal == 0:
135			return fmt.Sprintf("%d of %d observations succeeded; no observation was marked load-bearing, so nothing here proves an absence",
136				c.ObservationsOK, c.ObservationsTotal)
137		case c.AbsenceProvable:
138			return fmt.Sprintf("%d of %d load-bearing observations succeeded, so an absence found by them is evidence",
139				c.LoadBearingOK, c.LoadBearingTotal)
140		default:
141			sample := c.NotOK
142			if len(sample) > 6 {
143				sample = append(append([]string{}, sample[:6]...),
144					fmt.Sprintf("and %d more", len(c.NotOK)-6))
145			}
146			return fmt.Sprintf("%d of %d load-bearing observations succeeded; not observed: %s — an absence is not provable from this",
147				c.LoadBearingOK, c.LoadBearingTotal, strings.Join(sample, ", "))
148		}
149	}
150	
151	// AuditEntailment re-checks a produced findings document from the outside, so
152	// the same rule can be pointed at an artifact from a container or from the real
153	// host rather than only at an in-process run. It returns one line per
154	// violation.
155	func AuditEntailment(body []byte) []string {
156		var doc struct {
157			Findings []struct {
158				CheckID  string `json:"check_id"`
159				Status   string `json:"status"`
160				Evidence struct {
161					Detail       string       `json:"detail"`
162					Completeness Completeness `json:"completeness"`
163					Observations []struct {
164						Source        string `json:"source"`
165						Status        string `json:"status"`
166						Truncated     bool   `json:"truncated"`
167						LoadBearing   bool   `json:"load_bearing"`
168						AbsenceProven bool   `json:"absence_proven"`
169					} `json:"observations"`
170				} `json:"evidence"`
171				EntailmentViolation bool `json:"entailment_violation"`
172			} `json:"findings"`
173		}
174		dec := json.NewDecoder(bytes.NewReader(body))
175		if err := dec.Decode(&doc); err != nil {
176			return []string{"document is not a findings artifact: " + err.Error()}
177		}
178		var out []string
179		for _, f := range doc.Findings {
180			lbTotal, lbOK := 0, 0
181			var notOK []string
182			for _, o := range f.Evidence.Observations {
183				if !o.LoadBearing {
184					continue
185				}
186				lbTotal++
187				if !o.Truncated && (o.Status == "OK" || (o.Status == "ENOENT" && o.AbsenceProven)) {
188					lbOK++
189				} else {
190					notOK = append(notOK, o.Source+" ("+o.Status+")")
191				}
192			}
193			provable := lbTotal > 0 && lbOK == lbTotal
194	
195			if f.EntailmentViolation {
196				out = append(out, f.CheckID+": the engine recorded an entailment violation")
197			}
198			if f.Status == "pass" && lbTotal > 0 && lbOK != lbTotal {
199				out = append(out, f.CheckID+": status pass while load-bearing observations failed: "+strings.Join(notOK, ", "))
200			}
201			if phrase, claims := claimsCompleteness(f.Evidence.Detail); claims && !provable {
202				out = append(out, f.CheckID+": the detail claims "+quoteStr(phrase)+
203					" while "+itoaInt(lbTotal-lbOK)+" load-bearing observation(s) did not succeed")
204			}
205			if f.Evidence.Completeness.Statement == "" {
206				out = append(out, f.CheckID+": no generated completeness statement in evidence")
207			}
208		}
209		return out
210	}
211	
212	func quoteStr(s string) string { return `"` + s + `"` }
213	
214	func itoaInt(n int) string { return fmt.Sprintf("%d", n) }
