	body := procNetTCP("00000000:0017", "0A", "999")
	pad := strings.Repeat("   1: 0100007F:1F90 00000000:0000 0A 00000000:00000000 00:00000000 00000000     0        0 4242 1 0000 100 0\n", 12000)
