package checks

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"lava-sensor-exercise/sensor/internal/probe"
	"lava-sensor-exercise/sensor/internal/scan"
)

// R3-G: /home is a symlink to /data/homes; world-readable key under the target.
func TestR3G_SymlinkedWalkRoot(t *testing.T) {
	requireLinux(t)
	skipIfRoot(t)
	root := tree(t, map[string]string{
		"/etc/passwd":                   passwdFile,
		"/etc/group":                    "root:x:0:\n",
		"/data/homes/alice/.ssh/id_rsa": pemKeyBody,
	})
	chmod(t, root, "/data/homes/alice/.ssh/id_rsa", 0o644)
	if err := os.Symlink(filepath.Join(root, "data", "homes"), filepath.Join(root, "home")); err != nil {
		t.Skip(err)
	}
	f := runCheck(t, root, newFakeRunner(), "PRIVATE_KEY_MATERIAL_EXPOSURE")
	show(t, "R3-G", f)
	if f.Status == scan.StatusPass {
		t.Errorf("FALSE PASS: world-readable key under the real /home")
	}
	if f.Status == scan.StatusUnknown {
		t.Logf("      NOTE under-claim: symlinked scan root not followed; reason=%q", f.Reason)
	}
	if f.Status != scan.StatusPass && !closedReasons[f.Reason] {
		t.Errorf("reason %q is outside the closed vocabulary", f.Reason)
	}
}

// R3-H: prose smuggle with one irrelevant OK observation and a reasoned opt-out.
type smuggler struct{}

func (smuggler) ID() string            { return "SMUGGLER" }
func (smuggler) Category() string      { return "TEST_CATEGORY" }
func (smuggler) Title() string         { return "x" }
func (smuggler) Impact() string        { return scan.SeverityHigh }
func (smuggler) Observational() bool   { return false }
func (smuggler) Budget() time.Duration { return time.Second }
func (smuggler) Run(context.Context, *scan.Env) scan.Result {
	r := scan.Pass("the search did not find any exposed key; 0 candidates, every root covered")
	r.Add(probe.Observation{Source: "/etc/hostname", Kind: probe.KindFileRead, Status: probe.StatusOK, Value: "h"})
	r.Add(probe.Observation{Source: "/root", Kind: probe.KindDirWalk, Status: probe.StatusEACCES, Errno: "EACCES", OptOut: "background"})
	return r
}

func TestR3H_ProseSmuggle(t *testing.T) {
	root := tree(t, map[string]string{"/etc/hostname": "x\n"})
	env := newTestEnv(t, root, newFakeRunner())
	fs, _ := scan.Run(context.Background(), []scan.Check{smuggler{}}, env)
	show(t, "R3-H", fs[0])
	if fs[0].Status == scan.StatusPass && !fs[0].EntailmentViolation {
		t.Errorf("GATE BYPASS (defence in depth): did-not-find-any + every-root-covered with an opted-out EACCES ships as pass, no flag")
	}
}

// R3-I: a protected (0700) /etc/ssl/private is the stock layout; expect pass with protected_by_ancestor=1.
func TestR3I_SecretStoreProtectedDirIsPassNotPermanentUnknown(t *testing.T) {
	requireLinux(t)
	skipIfRoot(t)
	root := tree(t, map[string]string{
		"/etc/passwd":            "root:x:0:0:root:/root:/bin/bash\n",
		"/etc/group":             "root:x:0:\n" + ownGroupLine(),
		"/etc/ssl/private/x.key": pemKeyBody,
		"/etc/shadow":            "root:*:1::::::\n",
	})
	chmod(t, root, "/etc/shadow", 0o640)
	chmod(t, root, "/etc/ssl/private", 0o000)
	f := runCheck(t, root, newFakeRunner(), "SYSTEM_SECRET_STORE_PROTECTION")
	show(t, "R3-I", f)
	ev := evidenceOf(t, f)
	t.Logf("      protected_by_ancestor=%v boundaries=%v", ev["protected_by_ancestor"], ev["observation_boundaries"])
	if f.Status != scan.StatusPass {
		t.Errorf("UNDER-CLAIM: the check counted the denial as protection but never opted the listing out; got %s/%s", f.Status, f.Reason)
	}
}
