func TestTraversersUsesTheExecuteBitNotTheReadBit(t *testing.T) {
	requireLinux(t)
	skipIfRoot(t)
	root := tree(t, map[string]string{
		"/etc/passwd": passwdFile + "postgres:x:1500:1500::/var/lib/postgresql:/bin/bash\n",
