func r4show(t *testing.T, tag string, f scan.Finding) {
	t.Helper()
	ev := evidenceOf(t, f)
	comp, _ := ev["completeness"].(map[string]any)
	t.Logf("%s %s -> %s reason=%q viol=%v\n      detail=%s\n      completeness=%v", tag, f.CheckID, f.Status, f.Reason, f.EntailmentViolation, f.Evidence.Detail, comp["statement"])
}

func aclEntry(tag, perm uint16, id uint32) []byte {
	b := make([]byte, 8)
	binary.LittleEndian.PutUint16(b[0:2], tag)
	binary.LittleEndian.PutUint16(b[2:4], perm)
	binary.LittleEndian.PutUint32(b[4:8], id)
	return b
}

// setACL writes a version-2 system.posix_acl_access: owner/group_obj/other perms,
// one named user entry, mask = named|group_obj.
func setACL(t *testing.T, p string, ownerPerm, groupObjPerm, otherPerm uint16, namedUID uint32, namedPerm uint16) {
	t.Helper()
	const undef = 0xFFFFFFFF
	blob := make([]byte, 4)
	binary.LittleEndian.PutUint32(blob, 2)
	blob = append(blob, aclEntry(0x01, ownerPerm, undef)...)
	blob = append(blob, aclEntry(0x02, namedPerm, namedUID)...)
	blob = append(blob, aclEntry(0x04, groupObjPerm, undef)...)
	blob = append(blob, aclEntry(0x10, namedPerm|groupObjPerm, undef)...)
	blob = append(blob, aclEntry(0x20, otherPerm, undef)...)
	if err := syscall.Setxattr(p, "system.posix_acl_access", blob, 0); err != nil {
		t.Skipf("setxattr posix_acl_access unsupported here: %v", err)
	}
	fi, _ := os.Stat(p)
	t.Logf("      after ACL: %s mode=%04o", p, fi.Mode().Perm())
}

func r4passwd() string {
	return "root:x:0:0:root:/root:/bin/bash\nubuntu:x:" + strconv.Itoa(os.Getuid()) + ":" + gidStr() + ":Ubuntu:/home/ubuntu:/bin/bash\n"
}

func TestR4_NISCompatPlusLineMakesRootAReaderOfSudoers(t *testing.T) {
	requireLinux(t)
	root := tree(t, map[string]string{
		"/etc/passwd": "root:x:0:0:root:/root:/bin/bash\n+::::::\n",
		"/etc/group":  "root:x:0:\nshadow:x:42:\n",
	})
	env := newTestEnv(t, root, nil)
	mode, uid, gid := int64(0o440), int64(0), int64(0)
	r := env.Readers(&mode, &uid, &gid)
	t.Logf("R4-1 Readers(0440, root:root) with NIS plus line: determined=%v beyond=%v owner=%q members=%v desc=%q", r.Determined, r.BeyondOwner, r.OwnerName, r.GroupMember, r.Description)
	if r.BeyondOwner {
		t.Errorf("FALSE EXPOSURE: /etc/sudoers 0440 root:root is owner-only; a NIS compat plus line must not make root another reader")
	}
	root2 := tree(t, map[string]string{
		"/etc/passwd": "root:x:0:0:root:/root:/bin/bash\n",
		"/etc/group":  "root:x:0:\n+:::\n",
	})
	r2 := newTestEnv(t, root2, nil).Readers(&mode, &uid, &gid)
	t.Logf("R4-1b Readers(0440, root:root) with plus line in group: determined=%v beyond=%v group=%q members=%v desc=%q", r2.Determined, r2.BeyondOwner, r2.GroupName, r2.GroupMember, r2.Description)
	if r2.BeyondOwner {
		t.Errorf("FALSE EXPOSURE via /etc/group plus line")
	}
}

